import type { IconifyJSON } from '@iconify/types';
import { addCollection } from '@iconify/vue';
import { type Ref, ref } from 'vue';

// Offline registration of the blog public pages' icon sets — no runtime
// calls to the Iconify API. The TechSkillTag chips render devicon glyphs;
// heroicons are already registered at the app entries
// (resources/js/iconRegistry.ts). The devicon subset generated by
// `npm run icons:build` (scripts/build-icon-subsets.mjs) ships to the app
// only through this lazy dynamic import — the full ~5 MB raw pack would
// blow the page's JS budget. The `iconsReady` ref lets consumers render
// their `<Icon>` elements only after registration — a non-reactive
// storage would leave them empty until an unrelated re-render.

let registered = false;
const iconsReady = ref(false);

export function useBlogIconsReady(): Ref<boolean> {
    return iconsReady;
}

export function ensureBlogIcons(): void {
    if (registered || typeof window === 'undefined') {
        return;
    }

    registered = true;

    void import('@/iconSubsets/devicon.json')
        .then((devicon) => {
            addCollection((devicon as { default: IconifyJSON }).default);
            iconsReady.value = true;
        })
        .catch(() => {
            // Iconify falls back to its runtime fetch on an unregistered
            // name; the icons stay empty until a later registration.
            registered = false;
        });
}
